import {
	DefaultResourceLoader,
	ModelRuntime,
	SettingsManager,
	initTheme,
	type ExtensionRuntime,
} from "@earendil-works/pi-coding-agent";
import {
	configureHarnessHttp,
	createCodingRegistry,
	createHarnessSettings,
	findInitialAgentModel,
	type ExecutionEnvs,
	type ModelThinkingLevel,
} from "./harness-setup.ts";
import { createStandardExtensionFactories } from "./extension-bridge.ts";
import { createNestedToolExecutor, mountExtensionBridge } from "./extension-mount.ts";
import { getAgentDir, type SessionLocation } from "../session-storage.ts";
import { Harness, type ModelRef } from "@earendil-works/pi-durable";
import { openNodeSqliteStorage } from "@earendil-works/pi-durable/storage/sqlite/node";
import { type OpenDurableOptions, runtimeContext } from "./runtime-types.ts";
import { DynamicPromptSections } from "./prompt.ts";
import { DynamicCodemodeNamespaces } from "./codemode-namespaces.ts";
import type { SubagentPolicyHolder } from "@durable-zero/core";
import { loadSubagentPolicyHolder } from "./subagent-policy-ack.ts";

export interface LoadedHarnessEnvironment {
	modelRuntime: ModelRuntime;
	settingsManager: SettingsManager;
	harness: Harness;
	subagentPolicyHolder: SubagentPolicyHolder;
	initialModelRef?: ModelRef;
	initialThinkingLevel?: ModelThinkingLevel;
	fallbackMessage?: string;
	pendingReports: unknown[];
	getActiveModel: () => ModelRef | undefined;
	setActiveModelRef: (ref: ModelRef | undefined) => void;
	cleanup?: () => Promise<void>;
	extensionRunner?: import("@earendil-works/pi-coding-agent").ExtensionRunner;
	actionsDelegate?: import("./extension-mount.ts").ExtensionActionsDelegate;
	dynamicSections?: DynamicPromptSections;
	setNoticeForwarder?: (forwarder: (level: "info" | "warning" | "error", message: string) => void) => void;
	setActiveTools?: (tools: string[]) => void;
	getActiveTools?: () => string[];
}

function logRegError(kind: string, identifier: string, err: unknown): void {
	const msg = (err instanceof Error ? err.message : String(err)).toLowerCase();
	if (!msg.includes("already registered") && !msg.includes("duplicate")) {
		console.warn(`[RuntimeLoader] Failed to register ${kind} '${identifier}': ${err instanceof Error ? err.message : String(err)}`);
	}
}

function registerPendingProviders(modelRuntime: ModelRuntime, runtime: ExtensionRuntime): void {
	for (const { name, config } of runtime.pendingProviderRegistrations) {
		try { modelRuntime.registerProvider(name, config); } catch (err) { logRegError("provider", name, err); }
	}
	for (const { provider } of runtime.pendingNativeProviderRegistrations) {
		try { modelRuntime.registerNativeProvider(provider); } catch (err) { logRegError("native provider", provider?.id ?? "unknown", err); }
	}
	for (const { definition } of runtime.pendingVirtualModelRegistrations) {
		try { modelRuntime.registerVirtualModel(definition); } catch (err) { logRegError("virtual model", definition?.id ?? "unknown", err); }
	}
}

export async function loadHarnessEnvironment(
	location: SessionLocation,
	options: OpenDurableOptions,
	envs: ExecutionEnvs,
): Promise<LoadedHarnessEnvironment> {
	try {
		initTheme();
	} catch (err) {
		console.warn(`[RuntimeLoader] Theme initialization warning: ${err instanceof Error ? err.message : String(err)}`);
	}
	const deps = options.dependencies;
	const modelRuntime = deps?.modelRuntime ?? (await ModelRuntime.create());
	for (const provider of deps?.nativeProviders ?? []) {
		try {
			modelRuntime.registerNativeProvider(provider);
		} catch (err) {
			logRegError("native provider", provider?.id ?? "unknown", err);
		}
	}
	const settingsManager = deps?.settingsManager ?? SettingsManager.create(location.cwd);
	const extEnv = process.env.PI_ADDITIONAL_EXTENSIONS;
	const extPaths = [
		...(options.cli?.extensions ?? (options.cli?.extension ? [options.cli.extension] : [])),
		...(extEnv ? extEnv.split(",").map((s) => s.trim()).filter(Boolean) : []),
	];
	const resourceLoader =
		deps?.resourceLoader ??
		new DefaultResourceLoader({
			cwd: location.cwd,
			agentDir: getAgentDir(),
			settingsManager,
			extensionFactories: createStandardExtensionFactories(),
			additionalSkillPaths: options.cli?.skills,
			additionalExtensionPaths: extPaths.length > 0 ? extPaths : undefined,
			noExtensions: options.cli?.noGlobalExtensions ?? false,
		});
	if (!deps?.resourceLoader) {
		await resourceLoader.reload();
	}
	const extensionsResult = resourceLoader.getExtensions();

	registerPendingProviders(modelRuntime, extensionsResult.runtime);
	configureHarnessHttp(settingsManager);

	let activeModelRef: ModelRef | undefined;
	const getActiveModel = () => {
		if (activeModelRef) return activeModelRef;
		const p = settingsManager.getDefaultProvider();
		const m = settingsManager.getDefaultModel();
		return p && m ? { provider: p, modelId: m } : undefined;
	};

	const dynamicSections = deps?.dynamicSections ?? new DynamicPromptSections();
	const dynamicNamespaces = new DynamicCodemodeNamespaces();
	const settings = createHarnessSettings(settingsManager, getActiveModel);

	let subagentPolicyHolder: SubagentPolicyHolder | undefined;
	const getSubagentPolicy = () => {
		if (!subagentPolicyHolder) {
			throw new Error("Subagent policy accessed before runtime initialization");
		}
		return subagentPolicyHolder.getRecord();
	};

	const builtins = [
		...(deps?.builtins ?? []),
		...(options.builtins ?? options.plugins ?? []),
	];
	const promptOptions = deps?.prompt ?? options.prompt;
	const codingRegistry = await createCodingRegistry(
		settingsManager,
		location.cwd,
		getSubagentPolicy,
		{ ...promptOptions, resourceLoader, dynamicSections },
		dynamicNamespaces,
		builtins,
	);
	const registry = codingRegistry;

	const pendingReports: unknown[] = [];
	const report = (error: unknown) => pendingReports.push(error);

	let liveNoticeForwarder: ((level: "info" | "warning" | "error", message: string) => void) | undefined;
	let runnerRef: import("@earendil-works/pi-coding-agent").ExtensionRunner | undefined;
	const executeToolFn = createNestedToolExecutor(
		registry,
		() => runnerRef,
		() => envs.env({ cwd: location.cwd } as unknown as import("@earendil-works/pi-durable").EnvTarget),
	);
	const actionsDelegate: import("./extension-mount.ts").ExtensionActionsDelegate = {};
	const mounted = await mountExtensionBridge(
		location,
		modelRuntime,
		extensionsResult,
		registry,
		executeToolFn,
		report,
		dynamicSections,
		(level, message) => {
			if (liveNoticeForwarder) {
				liveNoticeForwarder(level, message);
			} else {
				pendingReports.push({ kind: "notice", level, message });
			}
		},
		settingsManager,
		dynamicNamespaces,
		actionsDelegate,
	);
	runnerRef = mounted.extensionRunner;

	let harness: Harness | undefined;
	const sessionCleanup = async () => {
		await codingRegistry.builtinRegistry.teardownAll().catch((err) => {
			console.warn("[RuntimeLoader] Built-in extension teardown error:", err);
		});
		await mounted.cleanup?.();
	};

	try {
		harness = await Harness.open(
			await openNodeSqliteStorage(location.database),
			{ models: modelRuntime, registry, settings, env: envs.env, onReport: report },
			runtimeContext,
		);

		subagentPolicyHolder = await loadSubagentPolicyHolder(harness);
	} catch (error) {
		await Promise.allSettled([
			harness?.close(runtimeContext),
			sessionCleanup(),
		]);
		throw error;
	}

	const initial = location.created
		? await findInitialAgentModel(settingsManager, modelRuntime, options.cli)
		: undefined;
	if (initial?.model) activeModelRef = initial.model;

	return {
		modelRuntime,
		settingsManager,
		harness,
		subagentPolicyHolder,
		initialModelRef: initial?.model,
		initialThinkingLevel: initial?.thinkingLevel,
		fallbackMessage: initial?.fallbackMessage,
		pendingReports,
		getActiveModel,
		setActiveModelRef: (ref) => { activeModelRef = ref; },
		cleanup: sessionCleanup,
		extensionRunner: mounted.extensionRunner,
		actionsDelegate,
		dynamicSections,
		setNoticeForwarder: (forwarder) => { liveNoticeForwarder = forwarder; },
		setActiveTools: mounted.setActiveTools,
		getActiveTools: mounted.getActiveTools,
	};
}

import type { DurableView } from "./runtime-types.ts";
import type { GraphScope, RuntimeGraphSnapshot, RuntimeTaskNode } from "@durable-zero/contracts";
import { MAX_LIVE_NODES } from "@durable-zero/contracts";
import { RuntimeGraphReceiptsCollector } from "./runtime-graph-receipts.ts";
import { RuntimeGraphConversations } from "./runtime-graph-conversations.ts";
import { TaskNames } from "./task-labels.ts";
import {
	extractTaskGraph,
	recordSubagentOwnership,
	buildMappedNode,
	recordTerminalWithDetails,
	type ViewSource,
	type HarnessGraphSource,
	type RuntimeGraphSourceOptions,
} from "./runtime-graph-mapper.ts";

export type { ViewSource, HarnessGraphSource, RuntimeGraphSourceOptions };

export class RuntimeGraphSource {
	private readonly viewSource: ViewSource;
	private readonly scope: GraphScope;
	private readonly debounceMs: number;
	private readonly maxDebounceMs: number;
	private readonly clock: () => number;
	private readonly receipts: RuntimeGraphReceiptsCollector;
	private readonly harness?: HarnessGraphSource;
	private readonly names = new TaskNames();
	private readonly listeners = new Set<(snapshot: RuntimeGraphSnapshot) => void>();
	private readonly epoch: string;
	private readonly conversations: RuntimeGraphConversations;
	private readonly nativeStartedAt = new Map<number, number>();
	private readonly recentEntries = new Map<number, unknown>();

	private revision = 0;
	private previousNodes = new Map<number, { conversationId: number; kind: string }>();
	private lastStructuralJson = "";
	private timer?: ReturnType<typeof setTimeout>;
	private firstScheduledAt?: number;
	private unsubscribeView?: () => void;
	private unsubscribeCommits?: () => void;
	private isDisposed = false;

	constructor(viewSource: ViewSource, scope: GraphScope, options?: RuntimeGraphSourceOptions) {
		this.viewSource = viewSource;
		this.scope = scope;
		this.debounceMs = options?.debounceMs ?? 250;
		this.maxDebounceMs = options?.maxDebounceMs ?? 1000;
		this.clock = options?.clock ?? Date.now;
		this.receipts = options?.receipts ?? new RuntimeGraphReceiptsCollector();
		this.harness = options?.harness;
		this.epoch = `epoch_${this.clock()}_${Math.random().toString(36).slice(2, 7)}`;
		this.conversations = new RuntimeGraphConversations(this.scope.rootConversationId);

		if (this.harness?.subscribeCommits) {
			this.unsubscribeCommits = this.harness.subscribeCommits((pub) => {
				for (const ch of pub.changes as Array<{ type?: string; value?: any }>) {
					if (ch?.type === "entry" && ch.value) {
						this.recentEntries.set(Number(ch.value.id), ch.value);
						if (this.recentEntries.size > 256) {
							const oldest = this.recentEntries.keys().next().value;
							if (oldest !== undefined) this.recentEntries.delete(oldest);
						}
					} else if (ch?.type === "task") {
						const taskVal = ch.value;
						const idNum = Number(taskVal?.id);
						if (taskVal?.startedAt) {
							if (this.nativeStartedAt.size >= 256) {
								const oldest = this.nativeStartedAt.keys().next().value;
								if (oldest !== undefined) this.nativeStartedAt.delete(oldest);
							}
							this.nativeStartedAt.set(idNum, Number(taskVal.startedAt));
						}
						if (taskVal?.state?.status === "terminal") {
							this.learnNames();
							recordTerminalWithDetails(this.receipts, taskVal, this.names, this.nativeStartedAt, this.viewSource.current(), this.recentEntries);
						}
						this.schedule();
					} else if (ch?.type === "conversation" && ch.value) {
						this.conversations.recordConversation(ch.value);
						this.schedule();
					}
				}
			});
		}
		this.unsubscribeView = this.viewSource.subscribe(() => {
			const cur = this.viewSource.current() as any;
			if (cur?.conversation?.entries) {
				this.receipts.backfillTokensFromEntries(cur.conversation.entries);
			}
			this.schedule();
		});
		this.schedule();
	}

	subscribe(listener: (snapshot: RuntimeGraphSnapshot) => void): () => void {
		this.listeners.add(listener);
		return () => this.listeners.delete(listener);
	}

	teardown(): void {
		if (this.isDisposed) return;
		this.isDisposed = true;
		if (this.timer !== undefined) {
			clearTimeout(this.timer);
			this.timer = undefined;
			this.publish();
		}
		this.unsubscribeCommits?.();
		this.unsubscribeView?.();
		this.listeners.clear();
	}

	private schedule(): void {
		if (this.isDisposed) return;
		const now = this.clock();
		if (this.firstScheduledAt === undefined) this.firstScheduledAt = now;
		const elapsed = now - this.firstScheduledAt;
		if (elapsed >= this.maxDebounceMs) {
			clearTimeout(this.timer);
			this.timer = undefined;
			this.publish();
			return;
		}
		clearTimeout(this.timer);
		const delay = Math.min(this.debounceMs, this.maxDebounceMs - elapsed);
		this.timer = setTimeout(() => { this.timer = undefined; this.publish(); }, Math.max(0, delay));
	}

	private publish(): void {
		this.firstScheduledAt = undefined;
		if (this.isDisposed) return;

		const current = this.viewSource.current();
		this.learnNames(current);
		const rawNodes = extractTaskGraph(current).tasks ?? {};
		const totalLiveCount = Object.keys(rawNodes).length;
		const liveNodeEntries = Object.entries(rawNodes).slice(0, MAX_LIVE_NODES);
		const currentLiveIds = new Set<number>();
		const mappedNodes: Record<string, RuntimeTaskNode> = {};
		const rootConvId = Number(this.scope.rootConversationId);

		for (const [key, node] of liveNodeEntries) {
			currentLiveIds.add(Number(node.id));
			this.conversations.recordFromLiveNode(Number(node.conversationId), Number(node.id), node.conversations);
			mappedNodes[key] = buildMappedNode(node, current, rootConvId, this.names, this.nativeStartedAt, this.clock);
		}

		const hasMissingReceipts = this.reconcileDisappearedNodes(currentLiveIds);
		this.previousNodes = new Map(
			liveNodeEntries.map(([_, n]) => [Number(n.id), { conversationId: Number(n.conversationId), kind: n.kind }]),
		);

		const completeness = (totalLiveCount > MAX_LIVE_NODES || hasMissingReceipts) ? "limited" : "complete";
		const conversations = this.conversations.snapshot();
		const receipts = this.receipts.getReceipts();
		const allTaskIds = new Set<number>();
		for (const key of Object.keys(rawNodes)) allTaskIds.add(Number(key));
		for (const r of receipts) allTaskIds.add(r.taskId);
		const stats = { liveCount: Object.keys(mappedNodes).length, terminalCount: receipts.length, totalCount: allTaskIds.size };

		const structuralJson = JSON.stringify({ nodes: mappedNodes, conversations, receipts, completeness, stats });
		if (structuralJson === this.lastStructuralJson) return;
		this.lastStructuralJson = structuralJson;

		const snapshot: RuntimeGraphSnapshot = {
			version: 1, scope: this.scope,
			observation: { epoch: this.epoch, revision: ++this.revision, observedAt: this.clock(), completeness },
			nodes: mappedNodes, conversations, receipts, stats,
		};
		for (const listener of this.listeners) listener(snapshot);
	}

	private learnNames(current?: unknown): void {
		const cur = current ?? this.viewSource.current();
		if (cur && typeof cur === "object" && "session" in cur && "conversation" in cur) {
			this.names.learn(cur as DurableView);
		}
		recordSubagentOwnership(this.conversations, cur, this.scope.rootConversationId);
	}

	private reconcileDisappearedNodes(currentLiveIds: Set<number>): boolean {
		let hasMissing = false;
		for (const [prevId] of this.previousNodes) {
			if (!currentLiveIds.has(prevId) && !this.receipts.hasReceipt(prevId)) {
				hasMissing = true;
				if (this.harness?.getTask) {
					void this.harness.getTask(prevId).then((task) => {
						if (task && task.state?.status === "terminal") {
							this.learnNames();
							recordTerminalWithDetails(this.receipts, task, this.names, this.nativeStartedAt, this.viewSource.current(), this.recentEntries);
							this.schedule();
						}
					}).catch(() => {});
				}
			}
		}
		return hasMissing;
	}
}

